const items = $input.all();
if (items.length === 0) return [];

// Gom nhóm theo từng task_id và tính điểm match %
const taskMap = {};

for (const item of items) {
  const data = item.json;
  const taskId = data.task_id;
  const required = data.required_skills || [];
  const memberSkills = data.member_skills || [];

  // Đếm số kỹ năng trùng nhau giữa Task và Member
  const matched = required.filter(rSkill => 
    memberSkills.some(mSkill => mSkill.toLowerCase().trim() === rSkill.toLowerCase().trim())
  );

  // Tính điểm Match Score %
  const score = required.length > 0 ? (matched.length / required.length) * 100 : 0;

  if (!taskMap[taskId]) {
    taskMap[taskId] = {
      task_id: taskId,
      task_title: data.task_title,
      best_member_id: data.member_id,
      best_member_name: data.member_name,
      best_score: score
    };
  } else if (score > taskMap[taskId].best_score) {
    taskMap[taskId].best_member_id = data.member_id;
    taskMap[taskId].best_member_name = data.member_name;
    taskMap[taskId].best_score = score;
  }
}

return Object.values(taskMap).map(res => ({ json: res }));
